  L.push("");

  if (routing?.decisions?.length) {
    L.push(`Files reviewed: ${routing.decisions.length} (${[...new Set(routing.decisions.map((d) => d.split(" -> ")[1]?.split(" ")[0]))].join(", ")})`);
    L.push("");
  }

  if (!findings.length) L.push("No issues found in the reviewed files.\n");

  let n = 0;
