async function main() {
  const dryRun = getInput("dry-run") === "true";
  const { owner, repo } = github_context.repo;
  const pr = github_context.payload.pull_request;
  if (!pr) {
    info("Not a pull_request event - nothing to review.");
    return;
  }
  info(`Reviewing PR #${pr.number}: ${pr.title}`);

  const octokit = getOctokit(getInput("github-token", { required: true }));
  const files = await fetchPrFiles(octokit, { owner, repo, pull_number: pr.number, headSha: pr.head.sha });
  info(`${files.length} changed file(s)`);

  const llm = makeLlm({
    apiKey: getInput("llm-api-key", { required: true }),
    baseUrl: getInput("llm-base-url", { required: true }),
    model: getInput("llm-model", { required: true }),
  });

  const result = await buildGraph(llm).invoke({ project: repo, files });
  info(result.routing.decisions.join("\n"));
  external_node_fs_namespaceObject.writeFileSync("review.md", result.markdown);

  if (dryRun) {
    info(result.markdown);
    return;
  }
  await upsertComment(octokit, { owner, repo, issue_number: pr.number }, result.markdown);

  // email review.md to the requested reviewer(s); never fail the run because of mail
  const smtp = {
    host: getInput("smtp-host"),
    port: getInput("smtp-port"),
    user: getInput("smtp-user"),
    pass: getInput("smtp-pass"),
  };
  const from = getInput("mail-from");
  if (!smtp.host || !from) {
    info("SMTP not configured - skipping email.");
    return;
  }
  const reviewers = await findEmails(octokit, { owner, repo, ref: pr.head.sha }, reviewerLogins(github_context.payload));
  if (!reviewers.length) warning("No reviewer requested on this PR - skipping email.");
  for (const r of reviewers) {
    if (!r.email) {
      warning(`No email for reviewer ${r.login} (add them to .github/reviewers.json) - skipping.`);
      continue;
    }
    try {
      await sendReview({
        smtp, from, to: r.email,
        subject: `[CAP review] ${repo} PR #${pr.number}: ${summaryLine(result.findings)}`,
        findings: result.findings, markdown: result.markdown, prUrl: pr.html_url,
      });
      info(`Review emailed to ${r.login}`);
    } catch (e) {
      warning(`Email to ${r.login} failed: ${e.message}`);
    }
  }
}

main().catch((e) => setFailed(e.message));

